python3 -I -c 'exec('"'"'import sys,json,math,wave,struct,functools,shutil,subprocess,os\nfrom pathlib import Path\nG=lambda b:functools.reduce(lambda n,v:n*257+v+1,b,1)\ndef D(n):\n a=[]\n while n>1:\n  n,r=divmod(n,257)\n  if not r:raise ValueError("G257 digit")\n  a.append(r-1)\n if n!=1:raise ValueError("G257 sentinel")\n return bytes(reversed(a))\nR,N=48000,4800\nF=list(range(400,2000,200))+[2200]\nT=[[math.sin(2*math.pi*f*j/R) for j in range(N)] for f in F]\nA=[min(1,j/240,(N-1-j)/240) for j in range(N)]\nV=[t[240:-240] for t in T]\nMAX=8192\ndef pack(b):\n assert len(b)<=MAX\n g=G(b);c=g.to_bytes((g.bit_length()+7)//8,"big")\n return b"AKO2"+struct.pack(">I",len(c))+c+bytes(v^255 for v in c)\ndef write(p,b):\n f=pack(b);B={v:struct.pack("<"+"h"*N,*(round(650*A[j]*sum(T[i][j] for i in range(9) if i==8 or v>>i&1)) for j in range(N))) for v in set(f)}\n with wave.open(str(p),"wb") as w:\n  w.setparams((1,2,R,0,"NONE","not compressed"))\n  for v in f:w.writeframesraw(B[v])\ndef read(p):\n with wave.open(str(p),"rb") as w:\n  n=w.getnframes();assert (w.getnchannels(),w.getsampwidth(),w.getframerate(),w.getcomptype())==(1,2,R,"NONE") and n%N==0 and 8<=n//N<=8+2*(MAX+32)\n  z=bytearray()\n  for _ in range(n//N):\n   x=struct.unpack("<"+"h"*N,w.readframes(N))[240:-240];a=[abs(sum(i*j for i,j in zip(x,t))) for t in V];assert a[8]>100000\n   z.append(sum(1<<i for i in range(8) if a[i]>.5*a[8]))\n m=struct.unpack(">I",z[4:8])[0];u=z[8:8+m];assert z[:4]==b"AKO2" and m>0 and len(z)==8+2*m and z[8+m:]==bytes(v^255 for v in u)\n b=D(int.from_bytes(u,"big"));assert pack(b)==z\n return b\ndef run(X,n):\n a=X["a"];b=a.get("blank","_");s=X["s"];p=X["p"];k=X["k"];t={int(i):v for i,v in X["t"].items()};h=a["halt"];d={}\n assert type(p)==type(k)==int and k>=0 and type(n)==int and 0<=n<=100000 and isinstance(b,str) and len(b)==1 and isinstance(s,str) and isinstance(h,list) and all(isinstance(i,str) for i in h) and all(isinstance(v,str) and len(v)==1 and v!=b for v in t.values())\n for q,c,u,v,m in a["rules"]:\n  assert all(isinstance(i,str) for i in (q,c,u,v)) and len(c)==len(v)==1 and type(m)==int and m in (-1,0,1) and (q,c) not in d\n  d[q,c]=(u,v,m)\n for _ in range(n):\n  if s in h or (s,t.get(p,b)) not in d:break\n  s,v,m=d[s,t.get(p,b)];t.pop(p,None) if v==b else t.__setitem__(p,v);p+=m;k+=1\n X.update(s=s,p=p,k=k,t={str(i):v for i,v in t.items()});return "HALTED" if s in h or (s,t.get(p,b)) not in d else "UNKNOWN"\ndef play(p):\n if os.getenv("AKASHA_PLAY","1")=="0":return\n for k,a in [("ffplay",["-nodisp","-autoexit","-loglevel","error"]),("afplay",[]),("paplay",[]),("aplay",["-q"])]:\n  if shutil.which(k):subprocess.run([k,*a,str(p)],check=True);return\n print("Open WAV in an audio player.")\nmode=sys.argv[1] if len(sys.argv)>1 else "run"\nif mode=="decode":print(read(sys.argv[2]).decode());sys.exit()\nassert mode in ("run","resume")\nif mode=="run":\n p=Path(sys.argv[2] if len(sys.argv)>2 else "AKASHA-Omega-TM.wav").resolve();n=int(sys.argv[3]) if len(sys.argv)>3 else 20;a=json.loads(sys.argv[4]) if len(sys.argv)>4 else {"rules":[["q","1","q","1",1],["q","_","H","1",0]],"input":"111","start":"q","halt":["H"]};X={"a":a,"s":a["start"],"p":0,"k":0,"t":{str(i):v for i,v in enumerate(a.get("input","")) if v!=a.get("blank","_")}}\nelse:\n X=json.loads(read(sys.argv[2]));p=Path(sys.argv[3]).resolve();n=int(sys.argv[4]) if len(sys.argv)>4 else 20\nstatus=run(X,n);b=json.dumps(X,sort_keys=True,separators=(",",":"),ensure_ascii=False).encode();write(p,b);assert read(p)==b;print(json.dumps({"system":"AKASHA-OMEGA-TM/v0.1","status":status,"steps":X["k"],"state":X["s"],"wav":str(p),"roundtrip":True},ensure_ascii=False),flush=True);play(p)\n'"'"')' "$@"
